config.code:
const t = String(context.vars.ticket).toLowerCase();
const has = (...w) => w.some((x) => t.includes(x));
let category = "other";
if (has("退款", "refund", "扣", "charged", "优惠券")) category = "refund";
else if (has("退货", "换", "return", "exchange", "收到的是", "received a")) category = "return";
else if (has("物流", "快递", "发货", "签收", "地址", "tracking", "delivery", "parcel")) category = "shipping";
else if (has("破", "裂", "漏", "冒烟", "缺", "broken", "scratch", "spark")) category = "damaged";
else if (has("发票", "invoice")) category = "invoice";
else if (has("登录", "账号", "积分", "验证码", "password", "log in")) category = "account";
else if (has("投诉", "律师", "态度", "complain", "unacceptable", "manager")) category = "complaint";
const urgent = has("冒烟", "起火", "律师", "盗", "扣了两次", "冻结", "spark", "charged twice", "breaker");
const priority = urgent ? "P1" : category === "other" ? "P3" : "P2";
const en = context.vars.lang === "English";
const order = context.vars.order_id;
const reply = en
  ? (order ? "Order " + order + ": " : "") + "Thanks for contacting us. Our team will review your request within 24 hours.\n— Qingyan Home Support"
  : "您好，" + (order ? "订单 " + order + " " : "") + "已收到您的反馈，我们会在 24 小时内处理。\n—— 青檐家居售后 · 阿檐";
return JSON.stringify({ category, priority, reply });
